class Solution {
public:
    long long singleDivisorTriplet(vector<int>& nums) {
        vector<long long> cnt(101, 0);
        for (int x : nums) cnt[x]++;
        long long ans = 0;
        for (int a = 1; a <= 100; a++) {
            if (!cnt[a]) continue;
            for (int b = a; b <= 100; b++) {
                if (!cnt[b]) continue;
                for (int c = b; c <= 100; c++) {
                    if (!cnt[c]) continue;
                    int s = a + b + c;
                    int divs = (s % a == 0) + (s % b == 0) + (s % c == 0);
                    if (divs == 1) {
                        if (a == b && b == c) {
                            ans += cnt[a] * (cnt[a] - 1) * (cnt[a] - 2);
                        } else if (a == b) {
                            ans += cnt[a] * (cnt[a] - 1) * cnt[c] * 3;
                        } else if (b == c) {
                            ans += cnt[b] * (cnt[b] - 1) * cnt[a] * 3;
                        } else {
                            ans += cnt[a] * cnt[b] * cnt[c] * 6;
                        }
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long singleDivisorTriplet(int[] nums) {
        long[] cnt = new long[101];
        for (int x : nums) cnt[x]++;
        long ans = 0;
        for (int a = 1; a <= 100; a++) {
            if (cnt[a] == 0) continue;
            for (int b = a; b <= 100; b++) {
                if (cnt[b] == 0) continue;
                for (int c = b; c <= 100; c++) {
                    if (cnt[c] == 0) continue;
                    int s = a + b + c;
                    int divs = (s % a == 0 ? 1 : 0) + (s % b == 0 ? 1 : 0) + (s % c == 0 ? 1 : 0);
                    if (divs == 1) {
                        if (a == b && b == c) {
                            ans += cnt[a] * (cnt[a] - 1) * (cnt[a] - 2);
                        } else if (a == b) {
                            ans += cnt[a] * (cnt[a] - 1) * cnt[c] * 3;
                        } else if (b == c) {
                            ans += cnt[b] * (cnt[b] - 1) * cnt[a] * 3;
                        } else {
                            ans += cnt[a] * cnt[b] * cnt[c] * 6;
                        }
                    }
                }
            }
        }
        return ans;
    }
