var singleDivisorTriplet = function(nums) {
    const cnt = new Array(101).fill(0n);
    for (const x of nums) cnt[x]++;
    let ans = 0n;
    for (let a = 1; a <= 100; a++) {
        if (cnt[a] === 0n) continue;
        for (let b = a; b <= 100; b++) {
            if (cnt[b] === 0n) continue;
            for (let c = b; c <= 100; c++) {
                if (cnt[c] === 0n) continue;
                const s = a + b + c;
                const divs = (s % a === 0 ? 1 : 0) + (s % b === 0 ? 1 : 0) + (s % c === 0 ? 1 : 0);
                if (divs === 1) {
                    if (a === b && b === c) {
                        ans += cnt[a] * (cnt[a] - 1n) * (cnt[a] - 2n);
                    } else if (a === b) {
                        ans += cnt[a] * (cnt[a] - 1n) * cnt[c] * 3n;
                    } else if (b === c) {
                        ans += cnt[b] * (cnt[b] - 1n) * cnt[a] * 3n;
                    } else {
                        ans += cnt[a] * cnt[b] * cnt[c] * 6n;
                    }
                }
            }
        }
    }
    return Number(ans);
};
